#!/usr/bin/env bash
# Swaps the last three icons in the About card (100%, 5.0, 4) for Tabler SVGs.
# Tabler is the icon set it-tools.tech uses. The SVGs are inlined, so they always
# show, with no icon-font download. Usage:  bash scripts/patch-about-icons.sh [index.html]
set -e
f="${1:-index.html}"
sed -i \
 -e '/class="ams-icon"/ s|<i class="ti ti-world"></i>|<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" style="color:#C8573E"><path d="M15 10l4.553 -2.276a1 1 0 0 1 1.447 .894v6.764a1 1 0 0 1 -1.447 .894l-4.553 -2.276v-4"/><path d="M3 8a2 2 0 0 1 2 -2h8a2 2 0 0 1 2 2v8a2 2 0 0 1 -2 2h-8a2 2 0 0 1 -2 -2l0 -8"/></svg>|' \
 -e '/class="ams-icon"/ s|<i class="ti ti-star-filled"></i>|<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" style="color:#D4A017"><path d="M6 9a6 6 0 1 0 12 0a6 6 0 1 0 -12 0"/><path d="M12 15l3.4 5.89l1.598 -3.233l3.598 .232l-3.4 -5.889"/><path d="M6.802 12l-3.4 5.89l3.598 -.233l1.598 3.232l3.4 -5.889"/></svg>|' \
 -e '/class="ams-icon"/ s|<i class="ti ti-pencil"></i>|<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" style="color:#8A6A4A"><path d="M5 7a4 4 0 1 0 8 0a4 4 0 1 0 -8 0"/><path d="M3 21v-2a4 4 0 0 1 4 -4h4a4 4 0 0 1 4 4v2"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/><path d="M21 21v-2a4 4 0 0 0 -3 -3.85"/></svg>|' \
 "$f"
echo "Done: $(grep -c 'class="ams-icon".*<svg' "$f") of 3 icons are now inline SVG in $f (the school icon stays as it was)."
